import numpy as np
from sklearn.metrics import (
    brier_score_loss,
    log_loss,
    roc_auc_score,
    average_precision_score,
)

def future_failure_labels(failure, warning_horizon):
    failure = np.asarray(failure, dtype=int)
    y = np.zeros_like(failure)
    n = len(failure)
    for i in range(n):
        end = min(n, i + warning_horizon + 1)
        y[i] = int(failure[i+1:end].max() if i + 1 < end else 0)
    return y

def threshold_at_fpr(y_true, score, max_fpr=0.05):
    y_true = np.asarray(y_true, dtype=int)
    score = np.asarray(score, dtype=float)
    negatives = score[y_true == 0]
    if len(negatives) == 0:
        return float(np.quantile(score, 0.95))
    q = max(0.0, min(1.0, 1.0 - max_fpr))
    return float(np.quantile(negatives, q))

def lead_times(failure, alerts):
    failure = np.asarray(failure, dtype=int)
    alerts = np.asarray(alerts, dtype=int)
    failure_idx = np.where(failure == 1)[0]
    if len(failure_idx) == 0:
        return []
    leads = []
    for fi in failure_idx:
        prior = np.where(alerts[:fi] == 1)[0]
        if len(prior):
            leads.append(int(fi - prior[-1]))
    return leads

def warning_metrics(failure, future_y, score, threshold):
    score = np.clip(np.asarray(score, dtype=float), 1e-9, 1 - 1e-9)
    future_y = np.asarray(future_y, dtype=int)
    alerts = (score >= threshold).astype(int)

    negatives = future_y == 0
    positives = future_y == 1

    fpr = float(alerts[negatives].mean()) if negatives.any() else None
    sensitivity = float(alerts[positives].mean()) if positives.any() else None

    out = {
        "threshold": float(threshold),
        "false_alarm_rate": fpr,
        "sensitivity": sensitivity,
        "brier": float(brier_score_loss(future_y, score)),
        "log_loss": float(log_loss(future_y, np.c_[1-score, score], labels=[0, 1])),
    }

    if len(np.unique(future_y)) > 1:
        out["roc_auc"] = float(roc_auc_score(future_y, score))
        out["average_precision"] = float(average_precision_score(future_y, score))
    else:
        out["roc_auc"] = None
        out["average_precision"] = None

    leads = lead_times(failure, alerts)
    out["median_lead_time"] = float(np.median(leads)) if leads else None
    out["n_failures_with_prior_alert"] = len(leads)
    return out

import numpy as np
import pandas as pd

def latent_proxy(graph_features, horizons=(1,3,7,23)):
    parts = [
        graph_features["distributed_contradiction"],
        graph_features["distributed_dispersion"],
        graph_features["missing_fraction"],
    ]
    for h in horizons:
        parts.extend([
            graph_features[f"dc_mean_{h}"],
            graph_features[f"dd_mean_{h}"],
            graph_features[f"missing_mean_{h}"],
        ])
    stack = pd.concat(parts, axis=1)
    ranked = stack.rank(pct=True)
    return ranked.mean(axis=1).fillna(0.0)

def neighborhood_reconstruction(df, edges, feature_columns):
    out = pd.DataFrame(index=df.index)
    for target in feature_columns:
        incoming = edges.loc[edges["target"] == target, "source"].tolist()
        incoming = [c for c in incoming if c in feature_columns]
        if incoming:
            out[f"{target}__neighbor_mean"] = df[incoming].astype(float).mean(axis=1)
        else:
            out[f"{target}__neighbor_mean"] = 0.0
    return out.fillna(0.0)

import numpy as np
from sklearn.metrics import brier_score_loss, log_loss, roc_auc_score, average_precision_score, accuracy_score

def binary_metrics(y, p):
    y = np.asarray(y, dtype=int)
    p = np.clip(np.asarray(p, dtype=float), 1e-9, 1-1e-9)
    out = {
        "brier": float(brier_score_loss(y,p)),
        "log_loss": float(log_loss(y, np.c_[1-p,p], labels=[0,1])),
        "accuracy_0.5": float(accuracy_score(y, (p>=0.5).astype(int))),
    }
    if len(np.unique(y)) > 1:
        out["roc_auc"] = float(roc_auc_score(y,p))
        out["average_precision"] = float(average_precision_score(y,p))
    else:
        out["roc_auc"] = None
        out["average_precision"] = None
    return out

def stratified_by_missingness(y, p, missing_fraction):
    mf = np.asarray(missing_fraction, dtype=float)
    q = np.quantile(mf, 0.5)
    low = mf <= q
    high = mf > q
    out = {}
    if low.any():
        out["low_missingness"] = binary_metrics(np.asarray(y)[low], np.asarray(p)[low])
    if high.any():
        out["high_missingness"] = binary_metrics(np.asarray(y)[high], np.asarray(p)[high])
    return out

