from collections import defaultdict
import numpy as np

def group_adjust(records):
    """
    Closely related animals share an independence group.
    Each group contributes its weighted mean, not an unbounded number of votes.
    """
    groups=defaultdict(list)
    for r in records:
        if not r.get("applicable",True):
            continue
        groups[r.get("independence_group",r["framework"])].append(r)

    out={}
    for name,rs in groups.items():
        weights=np.array([r["weight"] for r in rs],dtype=float)
        vals=np.array([r["normalized_effect"] for r in rs],dtype=float)
        if weights.sum() <= 0:
            value=0.0
        else:
            value=float(np.average(vals,weights=weights))
        out[name]={
            "frameworks":[r["framework"] for r in rs],
            "group_effect":value,
            "group_weight":float(min(1.0, weights.max() if len(weights) else 0.0)),
        }
    return out

def contradiction_metrics(records):
    applicable=[r for r in records if r.get("applicable",True) and r["weight"]>0]
    if not applicable:
        return {
            "support_weight":0.0,
            "contradiction_weight":0.0,
            "neutral_weight":0.0,
            "agreement_rate":None,
        }

    support=sum(r["weight"] for r in applicable if r["normalized_effect"]>0)
    contra=sum(r["weight"] for r in applicable if r["normalized_effect"]<0)
    neutral=sum(r["weight"] for r in applicable if r["normalized_effect"]==0)
    directional=[r for r in applicable if r["normalized_effect"]!=0]
    agreement=max(support,contra)/(support+contra) if (support+contra)>0 else None

    return {
        "support_weight":float(support),
        "contradiction_weight":float(contra),
        "neutral_weight":float(neutral),
        "agreement_rate":float(agreement) if agreement is not None else None,
    }

import numpy as np

def invariant_score(groups):
    if not groups:
        return 0.0
    effects=np.array([g["group_effect"] for g in groups.values()],dtype=float)
    weights=np.array([g["group_weight"] for g in groups.values()],dtype=float)
    if weights.sum()<=0:
        return 0.0
    mean=float(np.average(effects,weights=weights))
    # Penalize disagreement across independent groups.
    dispersion=float(np.average((effects-mean)**2,weights=weights))**0.5
    return float(mean*(1.0-min(1.0,dispersion)))

def replicated_support_fraction(records):
    supportive=[r for r in records if r.get("applicable",True) and r["normalized_effect"]>0]
    if not supportive:
        return 0.0
    return float(sum(1 for r in supportive if r.get("replicated",False))/len(supportive))

def provenance_adjusted_support(records):
    vals=[]
    weights=[]
    for r in records:
        if not r.get("applicable",True):
            continue
        vals.append(r["normalized_effect"])
        weights.append(r["weight"])
    if not vals or sum(weights)<=0:
        return 0.0
    return float(np.average(np.asarray(vals),weights=np.asarray(weights)))

from dataclasses import dataclass
from normalize import normalized_record
from consensus import group_adjust, contradiction_metrics
from metrics import invariant_score, replicated_support_fraction, provenance_adjusted_support

@dataclass
class TURTLEExperiment:
    effect_scale: float=0.02
    support_threshold: float=0.18
    conditional_threshold: float=0.05
    min_independent_groups: int=3

    def run(self, evidence):
        records=[normalized_record(r,self.effect_scale) for r in evidence]
        applicable=[r for r in records if r.get("applicable",True)]

        if not applicable:
            return {
                "records":records,
                "groups":{},
                "summary":{
                    "verdict":"INSUFFICIENT EVIDENCE",
                    "invariant_score":0.0,
                }
            }

        groups=group_adjust(records)
        cm=contradiction_metrics(records)
        inv=invariant_score(groups)
        rep=replicated_support_fraction(records)
        prov=provenance_adjusted_support(records)

        positive_groups=sum(1 for g in groups.values() if g["group_effect"]>0)
        negative_groups=sum(1 for g in groups.values() if g["group_effect"]<0)

        # Veto logic: records can declare a hard-failure flag.
        vetoes=[
            r["framework"] for r in applicable
            if r.get("veto_on_failure",False) and r["normalized_effect"]<0
        ]

        if vetoes:
            verdict="NOT SUPPORTED"
        elif len(groups) < self.min_independent_groups:
            verdict="INSUFFICIENT EVIDENCE"
        elif inv >= self.support_threshold and positive_groups >= self.min_independent_groups:
            verdict="COHERENTLY SUPPORTED"
        elif inv >= self.conditional_threshold and positive_groups > negative_groups:
            verdict="CONDITIONALLY SUPPORTED"
        elif inv <= -self.conditional_threshold or negative_groups > positive_groups:
            verdict="NOT SUPPORTED"
        else:
            verdict="MIXED / UNRESOLVED"

        return {
            "records":records,
            "groups":groups,
            "contradiction":cm,
            "summary":{
                "independent_group_count":len(groups),
                "positive_group_count":positive_groups,
                "negative_group_count":negative_groups,
                "invariant_score":inv,
                "replicated_support_fraction":rep,
                "provenance_adjusted_support":prov,
                "vetoes":vetoes,
                "verdict":verdict,
            },
            "interpretation":(
                "TURTLE synthesizes independent evidence groups; it does not convert many correlated "
                "framework outputs into independent confirmation."
            )
        }

