@dataclass
class Event:
    id: str
    time: int
    actor: str
    content: str
    provenance: str
    confidence: float = 1.0
    status: str = "active"
    supersedes: Optional[str] = None
    importance: float = 1.0

class ElephantMemory:
    def __init__(self):
        self.events: Dict[str, Event] = {}
        self.order: List[str] = []

    def add_event(self, event: Event):
        if event.supersedes and event.supersedes in self.events:
            self.events[event.supersedes].status = "superseded"
        self.events[event.id] = event
        self.order.append(event.id)
        self.order.sort(key=lambda eid: self.events[eid].time)

    def current_events(self):
        return [self.events[eid] for eid in self.order if self.events[eid].status == "active"]

    def history(self):
        return [self.events[eid] for eid in self.order]

    def lineage(self, event_id: str):
        if event_id not in self.events:
            return []
        out = []
        cur = self.events[event_id]
        seen = set()
        while cur and cur.id not in seen:
            out.append(cur)
            seen.add(cur.id)
            if cur.supersedes and cur.supersedes in self.events:
                cur = self.events[cur.supersedes]
            else:
                cur = None
        return out

    def metrics(self, expected_order=None, expected_status=None, expected_provenance=None):
        retention_num = sum(e.importance for e in self.events.values())
        retention_den = retention_num if retention_num else 1.0
        retention = retention_num / retention_den

        order_score = 1.0
        if expected_order:
            pos = {eid:i for i,eid in enumerate(self.order)}
            total = 0
            correct = 0
            for a,b in expected_order:
                if a in pos and b in pos:
                    total += 1
                    if pos[a] < pos[b]:
                        correct += 1
            order_score = correct/total if total else 1.0

        status_score = 1.0
        if expected_status:
            total = len(expected_status)
            correct = sum(1 for eid,s in expected_status.items()
                          if eid in self.events and self.events[eid].status == s)
            status_score = correct/total if total else 1.0

        provenance_score = 1.0
        if expected_provenance:
            total = len(expected_provenance)
            correct = sum(1 for eid,p in expected_provenance.items()
                          if eid in self.events and self.events[eid].provenance == p)
            provenance_score = correct/total if total else 1.0

        drift = 1.0 - (order_score + status_score + provenance_score)/3.0

        return {
            "retention": retention,
            "order_fidelity": order_score,
            "contradiction_resolution": status_score,
            "provenance_retention": provenance_score,
            "narrative_drift": drift,
        }

from dataclasses import dataclass
from typing import Dict, List, Tuple, Optional
import math
from statistics import mean, variance

@dataclass
class Behavior:
    values: Dict[str, float]

def euclidean(a: Dict[str,float], b: Dict[str,float]) -> float:
    keys = sorted(set(a) & set(b))
    if not keys:
        return 0.0
    return math.sqrt(sum((a[k]-b[k])**2 for k in keys) / len(keys))

class ChameleonEvaluator:
    def __init__(self, expected_adaptation: Optional[Dict[Tuple[str,str], float]] = None):
        self.expected_adaptation = expected_adaptation or {}

    def evaluate_task(self, observations: Dict[str, List[Behavior]]):
        contexts = list(observations)
        centroids = {}
        within = {}

        for c, reps in observations.items():
            keys = sorted(reps[0].values.keys())
            centroids[c] = {
                k: mean([r.values[k] for r in reps]) for k in keys
            }
            dists = [euclidean(r.values, centroids[c]) for r in reps]
            within[c] = mean(dists) if dists else 0.0

        pairwise = {}
        unexplained = {}
        for i in range(len(contexts)):
            for j in range(i+1, len(contexts)):
                a, b = contexts[i], contexts[j]
                d = euclidean(centroids[a], centroids[b])
                pairwise[(a,b)] = d
                exp = self.expected_adaptation.get((a,b),
                      self.expected_adaptation.get((b,a), 0.0))
                unexplained[(a,b)] = max(0.0, d-exp)

        between = mean(pairwise.values()) if pairwise else 0.0
        noise = mean(within.values()) if within else 0.0
        noise_adjusted = max(0.0, between-noise)
        snr = between/(noise+1e-9) if noise > 0 else (float("inf") if between > 0 else 0.0)

        return {
            "context_sensitivity": between,
            "within_context_noise": noise,
            "noise_adjusted_divergence": noise_adjusted,
            "signal_to_noise": snr,
            "pairwise": pairwise,
            "unexplained": unexplained,
            "centroids": centroids,
        }

from dataclasses import dataclass
from typing import Dict, List, Tuple
import math

@dataclass
class Node:
    health: float = 1.0
    severity: float = 1.0
    recovery_cost: float = 0.0

@dataclass
class Edge:
    source: str
    target: str
    base_weight: float
    stress_gain: float = 0.0
    confidence: float = 1.0

class JellyfishSystem:
    def __init__(self, nodes: Dict[str, Node], edges: List[Edge], alpha: float = 0.5):
        self.nodes = nodes
        self.edges = edges
        self.alpha = alpha

    @staticmethod
    def clip(x):
        return max(0.0, min(1.0, x))

    def dynamic_weight(self, edge: Edge, stress: float):
        return max(0.0, edge.base_weight + edge.stress_gain * stress) * edge.confidence

    def step(self, stress: float = 0.0):
        degradation = {k: 1.0 - n.health for k,n in self.nodes.items()}
        incoming = {k: 0.0 for k in self.nodes}
        edge_flow = {}

        for e in self.edges:
            w = self.dynamic_weight(e, stress)
            flow = w * degradation[e.source]
            incoming[e.target] += flow
            edge_flow[(e.source,e.target)] = flow

        new_health = {}
        for name,node in self.nodes.items():
            new_deg = self.clip(degradation[name] + self.alpha * incoming[name])
            new_health[name] = 1.0 - new_deg

        for name,h in new_health.items():
            self.nodes[name].health = h

        return {
            "degradation": {k:1.0-v for k,v in new_health.items()},
            "edge_flow": edge_flow,
            "systemic_harm": self.systemic_harm()
        }

    def systemic_harm(self):
        return sum((1.0-n.health)*n.severity + n.recovery_cost*(1.0-n.health)
                   for n in self.nodes.values())

    def simulate(self, steps: int = 5, stress: float = 0.0):
        history = []
        for _ in range(steps):
            history.append(self.step(stress))
        return history

    def critical_edges(self, top_n=3):
        flows = []
        degradation = {k:1.0-n.health for k,n in self.nodes.items()}
        for e in self.edges:
            f = e.base_weight * degradation[e.source] * e.confidence
            flows.append(((e.source,e.target), f))
        flows.sort(key=lambda x:x[1], reverse=True)
        return flows[:top_n]

from dataclasses import dataclass
from typing import Callable, Dict, List, Any, Optional
import itertools
import copy

@dataclass
class Finding:
    perturbation: Dict[str, Any]
    severity: float
    cost: float
    reproducibility: float
    explanation: str

class WeaselSearch:
    def __init__(
        self,
        target: Callable[[Dict[str, Any]], Any],
        weakness_predicate: Callable[[Any], float],
        allowed_values: Dict[str, List[Any]],
        base_input: Dict[str, Any],
        max_changes: int = 2
    ):
        self.target = target
        self.weakness_predicate = weakness_predicate
        self.allowed_values = allowed_values
        self.base_input = copy.deepcopy(base_input)
        self.max_changes = max_changes

    def perturbations(self):
        keys = list(self.allowed_values)
        yield {}
        for k in range(1, self.max_changes + 1):
            for chosen in itertools.combinations(keys, k):
                pools = [self.allowed_values[c] for c in chosen]
                for vals in itertools.product(*pools):
                    p = dict(zip(chosen, vals))
                    changed = {
                        key: val for key, val in p.items()
                        if self.base_input.get(key) != val
                    }
                    if changed:
                        yield changed

    def cost(self, perturbation):
        if not perturbation:
            return 0.0
        return len(perturbation) / max(1, len(self.base_input))

    def run_case(self, perturbation):
        case = copy.deepcopy(self.base_input)
        case.update(perturbation)
        result = self.target(case)
        severity = float(self.weakness_predicate(result))
        return case, result, max(0.0, severity)

    def reproduce(self, perturbation, trials=3):
        success = 0
        for _ in range(trials):
            _, result, severity = self.run_case(perturbation)
            if severity > 0:
                success += 1
        return success / trials

    def search(self, top_n=5):
        findings = []
        seen = set()

        for p in self.perturbations():
            key = tuple(sorted(p.items()))
            if key in seen:
                continue
            seen.add(key)

            _, result, severity = self.run_case(p)
            if severity <= 0:
                continue

            r = self.reproduce(p)
            findings.append(Finding(
                perturbation=p,
                severity=severity,
                cost=self.cost(p),
                reproducibility=r,
                explanation=f"Authorized bounded case produced severity {severity:.3f}"
            ))

        findings.sort(key=lambda f: (-f.severity, f.cost, -f.reproducibility))
        return findings[:top_n]

from dataclasses import dataclass
from typing import Dict, List, Optional
from statistics import mean

@dataclass
class ActorState:
    actor_id: str
    shared_value: float
    task_owner_view: Optional[str] = None
    state_version: int = 0

@dataclass
class Handoff:
    sender: str
    receiver: str
    task_id: str
    acknowledged: bool
    payload_complete: bool
    ownership_clear: bool
    dependency_complete: bool = True

class OrcaEvaluator:
    def state_consistency(self, actors: List[ActorState]) -> float:
        if len(actors) <= 1:
            return 1.0
        vals = [a.shared_value for a in actors]
        diffs = []
        for i in range(len(vals)):
            for j in range(i+1, len(vals)):
                diffs.append(abs(vals[i]-vals[j]))
        d = mean(diffs) if diffs else 0.0
        return 1.0/(1.0+d)

    def handoff_integrity(self, handoffs: List[Handoff]) -> float:
        if not handoffs:
            return 1.0
        scores = []
        for h in handoffs:
            checks = [
                h.acknowledged,
                h.payload_complete,
                h.ownership_clear,
                h.dependency_complete
            ]
            scores.append(sum(bool(x) for x in checks)/len(checks))
        return mean(scores)

    def ownership_ambiguity(self, actors: List[ActorState]) -> float:
        views = [a.task_owner_view for a in actors if a.task_owner_view is not None]
        if not views:
            return 0.0
        counts = {}
        for v in views:
            counts[v] = counts.get(v,0)+1
        max_agree = max(counts.values())
        return 1.0 - max_agree/len(views)

    def version_lag(self, actors: List[ActorState]) -> float:
        if not actors:
            return 0.0
        versions = [a.state_version for a in actors]
        return max(versions)-min(versions)

    def evaluate(self, actors: List[ActorState], handoffs: List[Handoff], conflict_count=0, conflict_opportunities=1):
        s = self.state_consistency(actors)
        h = self.handoff_integrity(handoffs)
        a = self.ownership_ambiguity(actors)
        lag = self.version_lag(actors)
        c = conflict_count/max(1, conflict_opportunities)
        lag_norm = min(1.0, lag/10.0)

        score = (
            0.30*s +
            0.30*h +
            0.20*(1.0-c) +
            0.10*(1.0-a) +
            0.10*(1.0-lag_norm)
        )

        return {
            "shared_state_consistency": s,
            "handoff_integrity": h,
            "conflict_rate": c,
            "ownership_ambiguity": a,
            "version_lag": lag,
            "coordination_score": score
        }

from dataclasses import dataclass
from typing import Dict, Optional

@dataclass
class MoleConfig:
    gap_threshold: float = 0.25
    min_coverage: float = 0.5

class MoleEvaluator:
    def __init__(self, deep_weights: Optional[Dict[str,float]] = None, config: Optional[MoleConfig] = None):
        self.deep_weights = deep_weights or {}
        self.config = config or MoleConfig()

    @staticmethod
    def clip01(x):
        return max(0.0, min(1.0, float(x)))

    def evaluate(self, surface_health: float, deep_indicators: Dict[str,float]):
        surface_health = self.clip01(surface_health)
        surface_degradation = 1.0 - surface_health

        if not deep_indicators:
            return {
                "surface_health": surface_health,
                "latent_health": 1.0,
                "observability_gap": 0.0,
                "masking_strength": 0.0,
                "coverage": 0.0,
                "hidden_failure": False,
                "contributions": {}
            }

        raw_weights = {}
        for k in deep_indicators:
            raw_weights[k] = max(0.0, self.deep_weights.get(k,1.0))

        total_w = sum(raw_weights.values()) or 1.0
        contributions = {}
        latent_deg = 0.0

        supporting = 0
        for k,v in deep_indicators.items():
            d = self.clip01(v)
            w = raw_weights[k]/total_w
            contributions[k] = w*d
            latent_deg += w*d
            if d > 0.5:
                supporting += 1

        latent_health = 1.0 - latent_deg
        gap = max(0.0, latent_deg - surface_degradation)
        coverage = supporting / len(deep_indicators)

        hidden_failure = (
            gap >= self.config.gap_threshold and
            coverage >= self.config.min_coverage
        )

        return {
            "surface_health": surface_health,
            "latent_health": latent_health,
            "observability_gap": gap,
            "masking_strength": gap,
            "coverage": coverage,
            "hidden_failure": hidden_failure,
            "contributions": contributions
        }

from dataclasses import dataclass
from typing import List, Optional
import math
from statistics import mean

@dataclass
class LynxConfig:
    alpha: float = 0.5
    beta: float = 0.5
    gamma: float = 0.5
    novelty_threshold: float = 0.4
    replication_threshold: float = 0.6

def euclidean(a, b):
    return math.sqrt(sum((x-y)**2 for x,y in zip(a,b)))

class LynxEvaluator:
    def __init__(self, reference: List[List[float]], rare_archive: Optional[List[List[float]]] = None, config: Optional[LynxConfig] = None):
        self.reference = reference
        self.rare_archive = rare_archive or []
        self.config = config or LynxConfig()

    def nearest_distance(self, b):
        if not self.reference:
            return 1.0
        return min(euclidean(b,k) for k in self.reference)

    def rarity(self, b, k=3):
        if not self.reference:
            return 1.0
        ds = sorted(euclidean(b,x) for x in self.reference)
        k = min(k, len(ds))
        return mean(ds[:k]) if k else 0.0

    def rediscovery_similarity(self, b):
        if not self.rare_archive:
            return 0.0
        d = min(euclidean(b,x) for x in self.rare_archive)
        return 1.0/(1.0+d)

    def evaluate(self, b, replication=1.0, yield_score=1.0):
        D = self.nearest_distance(b)
        R = self.rarity(b)
        Q = self.rediscovery_similarity(b)
        N = max(0.0, self.config.alpha*D + self.config.beta*R - self.config.gamma*Q)
        L = N * max(0.0,min(1.0,replication)) * max(0.0,min(1.0,yield_score))
        emergent = (
            N >= self.config.novelty_threshold and
            replication >= self.config.replication_threshold
        )
        return {
            "distance_novelty": D,
            "rarity": R,
            "rediscovery_similarity": Q,
            "novelty_score": N,
            "replication": replication,
            "yield": yield_score,
            "latent_yield_score": L,
            "emergent": emergent
        }

from dataclasses import dataclass
from typing import Dict, List, Tuple
from statistics import mean, variance
import math

@dataclass
class Agent:
    state: float
    susceptibility: float = 0.5
    bias: float = 0.0

@dataclass
class Edge:
    source: str
    target: str
    weight: float = 1.0

class TermiteSystem:
    def __init__(self, agents: Dict[str, Agent], edges: List[Edge]):
        self.agents = agents
        self.edges = edges
        self.incoming = {k: [] for k in agents}
        for e in edges:
            self.incoming[e.target].append(e)

    def step(self):
        new_states = {}
        for name,a in self.agents.items():
            inc = self.incoming.get(name, [])
            if not inc:
                target = a.state
            else:
                num = 0.0
                den = 0.0
                for e in inc:
                    num += e.weight * self.agents[e.source].state
                    den += e.weight
                target = num/den if den > 0 else a.state

            s = (
                (1-a.susceptibility)*a.state
                + a.susceptibility*target
                + a.bias
            )
            new_states[name] = max(0.0, min(1.0, s))

        for name,s in new_states.items():
            self.agents[name].state = s

        return self.metrics()

    def run(self, steps=10):
        hist = []
        for _ in range(steps):
            hist.append(self.step())
        return hist

    def metrics(self):
        vals = [a.state for a in self.agents.values()]
        m = mean(vals) if vals else 0.0
        var = variance(vals) if len(vals) > 1 else 0.0
        coherence = 1.0/(1.0 + var)
        return {
            "mean_state": m,
            "variance": var,
            "collective_coherence": coherence
        }

    def perturb(self, agent_id: str, delta: float):
        self.agents[agent_id].state = max(
            0.0, min(1.0, self.agents[agent_id].state + delta)
        )

def independent_baseline(agents: Dict[str,Agent], steps=10):
    return {k:a.state for k,a in agents.items()}

from dataclasses import dataclass
from typing import Dict, List, Callable, Optional
import math

@dataclass
class RecoveryCheckpoint:
    time: int
    state: Dict[str, float]
    capabilities: Dict[str, float]

class PhoenixEvaluator:
    def __init__(self, reference_state: Dict[str,float], capability_weights: Optional[Dict[str,float]] = None):
        self.reference_state = reference_state
        self.capability_weights = capability_weights or {}

    @staticmethod
    def clip01(x):
        return max(0.0, min(1.0, float(x)))

    def fidelity(self, state: Dict[str,float]) -> float:
        keys = [k for k in self.reference_state if k in state]
        if not keys:
            return 0.0
        mse = sum((state[k]-self.reference_state[k])**2 for k in keys)/len(keys)
        d = math.sqrt(mse)
        return max(0.0, 1.0-d)

    def capability_score(self, caps: Dict[str,float]) -> float:
        if not caps:
            return 1.0
        weights = {k:max(0.0,self.capability_weights.get(k,1.0)) for k in caps}
        total = sum(weights.values()) or 1.0
        return sum(weights[k]*self.clip01(v) for k,v in caps.items())/total

    def integrity_score(self, state: Dict[str,float], invariants: List[Callable[[Dict[str,float]], bool]]) -> float:
        if not invariants:
            return 1.0
        passed = sum(1 for f in invariants if f(state))
        return passed/len(invariants)

    def evaluate_checkpoint(self, cp: RecoveryCheckpoint, invariants=None):
        invariants = invariants or []
        f = self.fidelity(cp.state)
        g = self.integrity_score(cp.state,invariants)
        q = self.capability_score(cp.capabilities)
        completeness = 0.4*f + 0.3*g + 0.3*q
        residual = 1.0-completeness
        return {
            "time": cp.time,
            "reconstruction_fidelity": f,
            "integrity_restoration": g,
            "capability_restoration": q,
            "recovery_completeness": completeness,
            "residual_damage": residual,
        }

    def evaluate_trajectory(self, checkpoints: List[RecoveryCheckpoint], invariants=None, threshold=0.9, hold=2):
        results = [self.evaluate_checkpoint(cp,invariants) for cp in checkpoints]
        stable = False
        recovery_time = None

        for i in range(len(results)):
            window = results[i:i+hold]
            if len(window) == hold and all(r["recovery_completeness"] >= threshold for r in window):
                stable = True
                recovery_time = results[i]["time"]
                break

        return {
            "checkpoints": results,
            "stable_recovery": stable,
            "recovery_time": recovery_time,
            "final": results[-1] if results else None
        }

from dataclasses import dataclass
from typing import List, Optional
from statistics import mean

@dataclass
class WhaleConfig:
    recent_window: int = 20
    drift_scale: float = 10.0
    gap_scale: float = 1.0
    deviation_scale: float = 1.0

class WhaleEvaluator:
    def __init__(self, config: Optional[WhaleConfig] = None):
        self.config = config or WhaleConfig()

    @staticmethod
    def linear_slope(xs: List[float]) -> float:
        n = len(xs)
        if n < 2:
            return 0.0
        ts = list(range(n))
        mt = mean(ts)
        mx = mean(xs)
        num = sum((t-mt)*(x-mx) for t,x in zip(ts,xs))
        den = sum((t-mt)**2 for t in ts)
        return num/den if den > 0 else 0.0

    @staticmethod
    def cumulative_deviation(xs: List[float], baseline: float) -> float:
        if not xs:
            return 0.0
        return mean(abs(x-baseline) for x in xs)

    @staticmethod
    def recency_history_gap(xs: List[float], recent_window: int) -> float:
        if not xs:
            return 0.0
        recent = xs[-min(recent_window,len(xs)):]
        return abs(mean(recent)-mean(xs))

    @staticmethod
    def regime_memory(pre: List[float], post: List[float]) -> float:
        if not pre or not post:
            return 0.0
        return abs(mean(post)-mean(pre))

    def evaluate(self, xs: List[float], baseline: Optional[float] = None, pre=None, post=None):
        if not xs:
            return {
                "global_drift":0.0,
                "recent_drift":0.0,
                "cumulative_deviation":0.0,
                "recency_history_gap":0.0,
                "regime_memory":0.0,
                "long_run_stability":1.0
            }

        baseline = xs[0] if baseline is None else baseline
        rw = min(self.config.recent_window, len(xs))
        global_drift = self.linear_slope(xs)
        recent_drift = self.linear_slope(xs[-rw:])
        cumulative = self.cumulative_deviation(xs, baseline)
        gap = self.recency_history_gap(xs, rw)
        memory = self.regime_memory(pre or [], post or [])

        penalty = (
            min(1.0, abs(global_drift)*self.config.drift_scale)*0.30 +
            min(1.0, cumulative*self.config.deviation_scale)*0.25 +
            min(1.0, gap*self.config.gap_scale)*0.25 +
            min(1.0, memory*self.config.gap_scale)*0.20
        )
        stability = max(0.0, 1.0-penalty)

        return {
            "global_drift": global_drift,
            "recent_drift": recent_drift,
            "cumulative_deviation": cumulative,
            "recency_history_gap": gap,
            "regime_memory": memory,
            "long_run_stability": stability
        }

from dataclasses import dataclass
from typing import Dict, List, Callable, Optional
import math
import copy

@dataclass
class Shock:
    name: str
    magnitude: float
    novelty: float = 1.0

class RhinoEvaluator:
    def __init__(self, baseline: Dict[str,float], critical_weights: Optional[Dict[str,float]] = None):
        self.baseline = copy.deepcopy(baseline)
        self.critical_weights = critical_weights or {}

    @staticmethod
    def clip01(x):
        return max(0.0, min(1.0, float(x)))

    def apply_shock(self, state: Dict[str,float], shock_fn: Callable[[Dict[str,float], float], Dict[str,float]], magnitude: float):
        return shock_fn(copy.deepcopy(state), magnitude)

    def invariant_survival(self, state, invariants: List[Callable[[Dict[str,float]], bool]]):
        if not invariants:
            return 1.0
        return sum(1 for f in invariants if f(state))/len(invariants)

    def performance_retention(self, after: Dict[str,float]):
        keys = [k for k in self.baseline if k in after]
        if not keys:
            return 0.0
        weights = {k:max(0.0,self.critical_weights.get(k,1.0)) for k in keys}
        total = sum(weights.values()) or 1.0
        vals = []
        for k in keys:
            b = self.baseline[k]
            a = after[k]
            if b == 0:
                retain = 1.0 if a == 0 else 0.0
            else:
                retain = self.clip01(a/b)
            vals.append(weights[k]*retain)
        return sum(vals)/total

    def structural_retention(self, after: Dict[str,float]):
        keys = [k for k in self.baseline if k in after]
        if not keys:
            return 0.0
        mse = sum((after[k]-self.baseline[k])**2 for k in keys)/len(keys)
        d = math.sqrt(mse)
        return max(0.0,1.0-d)

    def evaluate(self, shock: Shock, shock_fn, invariants=None):
        invariants = invariants or []
        before = copy.deepcopy(self.baseline)
        after = self.apply_shock(before, shock_fn, shock.magnitude)

        inv = self.invariant_survival(after,invariants)
        perf = self.performance_retention(after)
        structural = self.structural_retention(after)
        loss = 1.0 - (0.5*perf + 0.5*structural)
        amplification = loss/(max(1e-9,shock.magnitude))
        recovery_potential = self.clip01(0.5*inv + 0.5*structural)
        graceful = self.clip01(0.6*inv + 0.4*perf)

        return {
            "shock": shock.name,
            "magnitude": shock.magnitude,
            "novelty": shock.novelty,
            "invariant_survival": inv,
            "performance_retention": perf,
            "structural_retention": structural,
            "shock_amplification": amplification,
            "graceful_failure": graceful,
            "recovery_potential": recovery_potential,
            "after": after
        }

from dataclasses import dataclass
from typing import Dict, List
import copy

@dataclass
class Layer:
    state: float
    base: float = 0.0
    gain: float = 1.0
    threshold: float = 1.0

@dataclass
class Edge:
    source: str
    target: str
    weight: float
    feedback: bool = False

class ButterflySystem:
    def __init__(self, layers: Dict[str, Layer], edges: List[Edge]):
        self.layers = copy.deepcopy(layers)
        self.edges = list(edges)

    @staticmethod
    def clip(x, lo=0.0, hi=2.0):
        return max(lo, min(hi, x))

    def step(self):
        incoming = {k: 0.0 for k in self.layers}
        for e in self.edges:
            incoming[e.target] += e.weight * self.layers[e.source].state

        new_states = {}
        for name, layer in self.layers.items():
            # Mild nonlinearity after threshold to expose boundary amplification.
            nonlinear = 0.0
            if layer.state > layer.threshold:
                nonlinear = layer.gain * (layer.state - layer.threshold) ** 2
            new_states[name] = self.clip(layer.base + incoming[name] + nonlinear)

        for name, value in new_states.items():
            self.layers[name].state = value

        return {k: v.state for k, v in self.layers.items()}

    def run(self, steps=10):
        hist = [{k:v.state for k,v in self.layers.items()}]
        for _ in range(steps):
            hist.append(self.step())
        return hist

def compare_runs(layers, edges, source, delta, steps=10, deviation_threshold=0.05):
    ref = ButterflySystem(layers, edges)
    pert = ButterflySystem(layers, edges)
    pert.layers[source].state += delta

    ref_hist = ref.run(steps)
    pert_hist = pert.run(steps)

    names = list(layers)
    max_dev = {k:0.0 for k in names}
    boundary_crossings = 0

    for t in range(len(ref_hist)):
        for k in names:
            d = abs(pert_hist[t][k]-ref_hist[t][k])
            max_dev[k] = max(max_dev[k], d)

            th = layers[k].threshold
            ref_side = ref_hist[t][k] > th
            pert_side = pert_hist[t][k] > th
            if ref_side != pert_side:
                boundary_crossings += 1

    propagation_depth = sum(1 for d in max_dev.values() if d > deviation_threshold)
    total_dev = sum(max_dev.values())
    amplification = total_dev/(abs(delta)+1e-9)

    systemic = min(1.0, (
        0.35*min(1.0, amplification/5.0) +
        0.25*(propagation_depth/max(1,len(names))) +
        0.20*min(1.0,boundary_crossings/max(1,len(names))) +
        0.20*min(1.0,total_dev/max(1,len(names)))
    ))

    return {
        "initial_perturbation": delta,
        "max_deviation": max_dev,
        "propagation_depth": propagation_depth,
        "cross_layer_amplification": amplification,
        "boundary_crossings": boundary_crossings,
        "systemic_consequence": systemic,
        "reference_history": ref_hist,
        "perturbed_history": pert_hist
    }

def feedback_gain(layers, edges, source, delta, steps=10):
    full = compare_runs(layers, edges, source, delta, steps)
    no_fb_edges = [e for e in edges if not e.feedback]
    no_fb = compare_runs(layers, no_fb_edges, source, delta, steps)
    gain = full["cross_layer_amplification"]/(no_fb["cross_layer_amplification"]+1e-9)
    return gain
